"""How much of the authors' test set involves users and resources that also appear in their training set? (Context for the unseen-entity experiment: with a random split most test tuples are about entities the model has already seen.)
Reads the authors' own train/test files (columns 0 and 1 are the user id and the resource id, as run_cell.py's cold-split code uses them) and writes paper/generated/entity_overlap.csv and paper/generated/overlap.tex.
usage (from the repository root, with the submodule checked out): python -I scripts/entity_overlap.py"""
import csv, os, sys
import numpy as np
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "src", "dlbac_revisited")); import dlbac as D
OUT = "paper/generated"; os.makedirs(OUT, exist_ok=True); rows = []
for ds in D.SYNTHETIC:
    tr, te = D.rd(f"{D.ROOT}/synthetic/{ds}/train_{ds}.sample"), D.rd(f"{D.ROOT}/synthetic/{ds}/test_{ds}.sample")
    u, r = np.isin(te[:, 0], np.unique(tr[:, 0])), np.isin(te[:, 1], np.unique(tr[:, 1])); rows.append((ds, len(te), u.mean(), r.mean(), (u & r).mean()))
with open(f"{OUT}/entity_overlap.csv", "w", newline="") as f:
    w = csv.writer(f); w.writerow(["dataset", "test_tuples", "user_seen", "resource_seen", "both_seen"]); [w.writerow([d, n, f"{a:.3f}", f"{b:.3f}", f"{c:.3f}"]) for d, n, a, b, c in rows]
both = [c for *_, c in rows]
with open(f"{OUT}/overlap.tex", "w") as f:
    f.write("% generated by scripts/entity_overlap.py: do not edit\n"); f.write(f"\\newcommand{{\\overlapMin}}{{{100 * min(both):.0f}}}\n\\newcommand{{\\overlapMax}}{{{100 * max(both):.0f}}}\n"); f.write(f"\\newcommand{{\\unseenMin}}{{{100 - 100 * max(both):.0f}}}\n\\newcommand{{\\unseenMax}}{{{100 - 100 * min(both):.0f}}}\n")
for d, n, a, b, c in rows: print(f"{d:18s} test tuples {n:6d}  user seen {a:.3f}  resource seen {b:.3f}  both seen {c:.3f}")
print(f"share of test tuples with both the user and the resource seen in training: {100 * min(both):.1f}% to {100 * max(both):.1f}%")
